    options_tr: { A: 'Geriye dönük aydınlanma', B: 'İstemsiz bellek', C: 'Duyusal anamnez', D: 'Geri kazanılmış bilinç', E: 'İlksel anımsama' },
    answer: 'B',
    difficulty: 2,
    explanation: 'The madeleine episode in Proust\'s novel is the canonical literary example of \'involuntary memory\' (mémoire involontaire), a spontaneous recollection triggered by sensation rather than deliberate effort.',
