    answer: 'B',
    difficulty: 2,
    explanation: 'In Goethe\'s drama, Mephistopheles wagers that he can make Faust wish a fleeting moment would last forever, thereby winning his soul; the deal is structured as this bet rather than a straightforward sale.',
