    text_tr: 'Henrik Ibsen\'in \'Bir Bebek Evi\' (1879) adlı oyununun sonu — Nora\'nın kendini bulmak için kocasını ve çocuklarını terk etmesi — seyirciyi öylesine rahatsız etmişti ki, Ibsen oyunun Almanya\'daki galası için alternatif bir son yazması yönünde baskı gördü. Ibsen bu baskıya boyun eğdi mi?',
    options: { A: 'No, he refused and the play was simply banned in Germany', B: 'Yes, and this became the definitive ending performed everywhere since', C: 'No, he let the German theater cut the ending scene entirely instead', D: 'Yes, he wrote an alternate ending in which Nora stays, later calling it a \'barbaric outrage\' forced upon him', E: 'Yes, but only as a joke that was never actually staged' },
    options_tr: { A: 'Hayır, reddetti ve oyun Almanya\'da basitçe yasaklandı', B: 'Evet, ve bu son o günden beri her yerde sahnelenen kesin son oldu', C: 'Hayır, bunun yerine Alman tiyatrosunun son sahneyi tamamen kesmesine izin verdi', D: 'Evet, Nora\'nın kaldığı alternatif bir son yazdı ve bunu sonradan kendisine dayatılmış \'barbarca bir hakaret\' olarak nitelendirdi', E: 'Evet, ama bu yalnızca sahnelenmeyen bir şakaydı' },
    answer: 'D',
