    text: 'Turkish poet Nazım Hikmet spent much of the 1940s imprisoned by the Turkish government for his political views. Which major work, an epic poem cycle portraying ordinary lives across Turkey, did he largely write during this imprisonment?',
    text_tr: 'Türk şair Nazım Hikmet, 1940\'ların büyük bölümünü siyasi görüşleri yüzünden Türk hükümeti tarafından hapsedilmiş olarak geçirmiştir. Türkiye genelinde sıradan insanların hayatlarını konu alan destansı şiir dizisini büyük ölçüde bu hapis döneminde yazmıştır; bu eser hangisidir?',
