    text_tr: 'Robert Browning\'in "Son Düşesim" (My Last Duchess) şiirinde bir dük, merhum eşinin portresini bir ziyaretçiye gösterirken farkında olmadan kendi zalimliğini ve kıskançlığını ele verir. Bu şiir, bir konuşmacının sessiz bir dinleyiciye seslendiği hangi şiir biçiminin klasik bir örneğidir?',
    options: { A: 'Dramatic monologue', B: 'Ode', C: 'Elegy', D: 'Villanelle', E: 'Aubade' },
    options_tr: { A: 'Dramatik monolog', B: 'Ode', C: 'Ağıt (elegy)', D: 'Villanelle', E: 'Aubade' },
    answer: 'A',
    difficulty: 2,
    explanation: 'The dramatic monologue lets a single speaker\'s own words, addressed to a silent listener, unintentionally expose their character, exactly what happens as Browning\'s duke describes his duchess\'s portrait.',
