    text: 'The "Táin Bó Cúailnge" ("The Cattle Raid of Cooley"), centerpiece of Ireland\'s Ulster Cycle, recounts a war triggered by a rival queen\'s desire to possess a prized bull. Who is this queen who launches the invasion?',
