    options: { A: 'Medb of Connacht', B: 'Deirdre of the Sorrows', C: 'Gráinne of the Fianna', D: 'Scáthach of Skye', E: 'Macha of Ulster' },
    options_tr: { A: 'Connacht\'lı Medb', B: 'Kederli Deirdre', C: 'Fianna\'lı Gráinne', D: 'Skye\'lı Scáthach', E: 'Ulster\'lı Macha' },
    answer: 'A',
    difficulty: 2,
    explanation: 'Queen Medb of Connacht invades Ulster to seize the Brown Bull of Cooley after failing to match her husband\'s wealth, setting the events of the "Táin" in motion, with the hero Cú Chulainn defending Ulster virtually single-handedly.',
