    text_tr: 'Raymond Queneau\'nun 1947 tarihli "Exercises in Style" (Biçem Alıştırmaları) adlı kitabı, önemsiz bir olayı, bir adamın Paris otobüsündeki tuhaf karşılaşmasını, dikkat çekici sayıda kez, her seferinde farklı bir edebi üslupla yeniden anlatır. Kitapta kaç farklı versiyon bulunur?',
