    text_tr: 'Allen Ginsberg ve Jack Kerouac gibi yazarları içeren 20. yüzyıl ortası Amerikan edebiyat akımı Beat Kuşağı, en çok hangi üslupsal ve tematik özellikle özdeşleştirilir?',
    options: { A: 'Spontaneous, free-flowing prose and verse rejecting mainstream conformity', B: 'Tightly rhymed sonnets celebrating pastoral English life', C: 'Detached, minimalist realism about domestic suburban routine', D: 'Formal historical epics about ancient Rome', E: 'Strict adherence to Victorian melodrama' },
    options_tr: { A: 'Ana akım uyumculuğu reddeden kendiliğinden, akıcı düzyazı ve şiir', B: 'İngiliz kırsal yaşamını öven sıkı kafiyeli soneler', C: 'Banliyö yaşamı rutini hakkında mesafeli, minimalist gerçekçilik', D: 'Antik Roma hakkında biçimsel tarihi destanlar', E: 'Viktorya dönemi melodramına sıkı bağlılık' },
    answer: 'A',
    difficulty: 2,
    explanation: 'Beat writers championed spontaneous prose and free verse, rejecting mainstream 1950s conformity in favor of raw, confessional, improvisational expression.',
