    options: { A: 'Meaningless or purposeless, often conveyed through illogical dialogue and circular plots', B: 'Perfectly rational and governed by clear moral order', C: 'Structured entirely around strict Aristotelian unity of time and place', D: 'Optimistic and steadily progressing toward resolution', E: 'Dominated by realistic, naturalistic dialogue about everyday chores' },
    options_tr: { A: 'Anlamsız veya amaçsız, çoğunlukla mantıksız diyaloglar ve döngüsel olay örgüleriyle aktarılan', B: 'Tamamen akla uygun ve açık bir ahlaki düzenle yönetilen', C: 'Tamamen Aristotelesçi zaman ve mekan birliğine göre yapılandırılmış', D: 'İyimser ve istikrarlı biçimde bir çözüme doğru ilerleyen', E: 'Günlük ev işleri hakkında gerçekçi, doğalcı diyaloglarla domine edilen' },
